const W=3120,H=2500,PHOTO_H=2080;
const SW=110,GAP=40;
const canvas=document.getElementById('canvas');
const ctx=canvas.getContext('2d');
const file=document.getElementById('file');
const drop=document.getElementById('drop');
const fit=document.getElementById('fit');
const zoom=document.getElementById('zoom');
const x=document.getElementById('x');
const y=document.getElementById('y');
const swatches=document.getElementById('swatches');

let img=new Image();
let ready=false;
let palette=['#b7aaa5','#93adbf','#31535c'];

function hexToRgb(hex){
  return hex.match(/\w\w/g).map(v=>parseInt(v,16));
}

function colorDistance(a,b){
  return Math.sqrt((a[0]-b[0])**2+(a[1]-b[1])**2+(a[2]-b[2])**2);
}

function extractPalette(){
  const c=document.createElement('canvas'), w=120,h=80;
  c.width=w;c.height=h;
  const q=c.getContext('2d');
  q.drawImage(img,0,0,w,h);
  const data=q.getImageData(0,0,w,h).data;
  const pts=[];
  for(let i=0;i<data.length;i+=16){
    const r=data[i],g=data[i+1],b=data[i+2];
    if(Math.max(r,g,b)-Math.min(r,g,b)<8) continue;
    pts.push([r,g,b]);
  }
  if(!pts.length)return;
  // Simple lightweight k-means: enough for an offline browser tool.
  let centers=[pts[0],pts[Math.floor(pts.length/3)],pts[Math.floor(pts.length*2/3)]];
  for(let it=0;it<7;it++){
    const groups=[[],[],[]];
    for(const p of pts){
      let bi=0,bd=Infinity;
      centers.forEach((c,i)=>{const d=colorDistance(p,c);if(d<bd){bd=d;bi=i}});
      groups[bi].push(p);
    }
    centers=groups.map((g,i)=>{
      if(!g.length)return centers[i];
      return g.reduce((a,p)=>[a[0]+p[0],a[1]+p[1],a[2]+p[2]],[0,0,0]).map(v=>Math.round(v/g.length));
    });
  }
  palette=centers.map(c=>'#'+c.map(v=>v.toString(16).padStart(2,'0')).join(''));
}

function draw(){
  ctx.clearRect(0,0,W,H);
  ctx.fillStyle='#fff';
  ctx.fillRect(0,0,W,H);

  if(ready){
    // 將照片區域的起始 y 座標設定為 210 (上方留白 210px)
    const region={x:0, y:210, w:W, h:PHOTO_H}; 
    const iw=img.naturalWidth, ih=img.naturalHeight;
    let scale;
    if(fit.value==='contain') scale=Math.min(region.w/iw,region.h/ih);
    else scale=Math.max(region.w/iw,region.h/ih);
    scale*=Number(zoom.value);

    const dw=iw*scale, dh=ih*scale;
    const maxX=Math.max(0,dw-region.w), maxY=Math.max(0,dh-region.h);
    const px=(region.w-dw)/2 - Number(x.value)*maxX/2;
    const py=(region.h-dh)/2 - Number(y.value)*maxY/2;

    ctx.save();
    ctx.beginPath();
    // 裁切遮罩套用 region 的 y 與 h
    ctx.rect(region.x, region.y, region.w, region.h); 
    ctx.clip();
    // 繪製圖片時，加上 region.x 與 region.y 的座標偏移
    ctx.drawImage(img, region.x+px, region.y+py, dw, dh); 
    ctx.restore();
  }

  // Bottom white margin is 420 px.
  // Three 112px squares with 37px gaps, right aligned with 70px margin.
  const total=SW*3+GAP*2;
  const right=74;
  const bottom=50;
  const top=H-bottom-SW;
  const startX=W-right-total;

  palette.forEach((c,i)=>{
    ctx.fillStyle=c;
    ctx.fillRect(startX+i*(SW+GAP),top,SW,SW);
  });

  swatches.innerHTML=palette.map(c=>`<div class="swatch" title="${c}" style="background:${c}"></div>`).join('');
}

function loadFile(f){
  if(!f)return;
  const url=URL.createObjectURL(f);
  img=new Image();
  img.onload=()=>{
    ready=true;
    extractPalette();
    URL.revokeObjectURL(url);
    draw();
  };
  img.src=url;
}

drop.onclick=()=>file.click();
file.onchange=e=>loadFile(e.target.files[0]);
['dragover','dragenter'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.style.background='#fafafa'}));
['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.style.background=''}));
drop.addEventListener('drop',e=>loadFile(e.dataTransfer.files[0]));
[fit,zoom,x,y].forEach(el=>el.addEventListener('input',draw));

document.getElementById('download').onclick=()=>{
  const a=document.createElement('a');
  a.download='postcard_3120x2500.png';
  a.href=canvas.toDataURL('image/png');
  a.click();
};

// 你的範例照片先作為預覽。
img.onload=()=>{ready=true;extractPalette();draw();};
img.src='data:image/jpeg;base64,';
